SELECT

FROM t_requirement tr
LEFT JOIN t_requirement_project tp ON tr.project_id = tp.project_id


        AND INSTR(tr.req_number, #{queryForm.reqNumber})


        AND INSTR(tr.title, #{queryForm.title})


        AND tr.project_id = #{queryForm.projectId}


        AND tr.status = #{queryForm.status}


        AND DATE_FORMAT(tr.create_time, '%Y-%m-%d') >= #{queryForm.startTime}


        AND DATE_FORMAT(tr.create_time, '%Y-%m-%d') <= #{queryForm.endTime}


ORDER BY tr.create_time DESC

SELECT

FROM t_requirement tr
LEFT JOIN t_requirement_project tp ON tr.project_id = tp.project_id


        AND DATE_FORMAT(tr.create_time, '%Y-%m-%d') = #{queryForm.date}


        AND tp.project_code = #{queryForm.projectCode}


        AND tr.status = #{queryForm.status}


ORDER BY tr.create_time DESC, tr.requirement_id DESC
